CREATE OR REPLACE FUNCTION public.guard_trip_library_record_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare write_time timestamptz := clock_timestamp();
begin
  if tg_op = 'INSERT' then
    if new.storage_revision is distinct from 1 then
      raise exception using errcode='23514', message='INITIAL_STORAGE_REVISION_MUST_BE_ONE';
    end if;
    -- Creation may start as draft or saved. History is entered only from an existing saved row.
    if new.library_state = 'history' then
      raise exception using errcode='23514', message='HISTORY_REQUIRES_SAVED_TRANSITION';
    end if;
    new.created_at := write_time;
  else
    if old.library_state = 'history' then
      raise exception using errcode='55000', message='IMMUTABLE_TRIP_HISTORY';
    end if;
    if new.id is distinct from old.id or new.owner_user_id is distinct from old.owner_user_id
      or new.creation_key is distinct from old.creation_key
      or new.preference_snapshot is distinct from old.preference_snapshot
      or new.preference_source_revision is distinct from old.preference_source_revision then
      raise exception using errcode='55000', message='IMMUTABLE_TRIP_CREATION';
    end if;
    if old.storage_revision = 2147483647 or new.storage_revision is distinct from old.storage_revision + 1 then
      raise exception using errcode='40001', message='STALE_STORAGE_REVISION';
    end if;
    if not ((old.library_state='draft' and new.library_state in ('draft','saved'))
      or (old.library_state='saved' and new.library_state in ('saved','history'))) then
      raise exception using errcode='23514', message='INVALID_TRIP_LIBRARY_TRANSITION';
    end if;
    new.created_at := old.created_at;
    if new.library_state = 'history' then
      -- One DB-owned instant, ignoring caller-supplied freeze time; never date-driven.
      new.frozen_at := write_time;
    end if;
  end if;
  new.updated_at := write_time;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.is_companion_travel_profile_v1(payload jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  allowed constant jsonb := '{
    "mobilityNeeds":["reduce_walking","reduce_stairs","stroller","child_seat","accessible_route","more_rest"],
    "diningNeeds":["dietary_restriction","food_allergy_notice","vegetarian","child_meal","other_dietary_need"],
    "activityInterests":["animals","outdoor","museums","photography","rides"]
  }';
  item record;
begin
  if payload is null or jsonb_typeof(payload) <> 'object' then return false; end if;
  if octet_length(payload::text) > 8192 or
    not payload ?& array['schemaVersion','mobilityNeeds','diningNeeds','activityInterests'] or
    (select count(*) from jsonb_object_keys(payload)) <> 4 or
    payload->'schemaVersion' <> '"1.0"'::jsonb then return false; end if;
  for item in select * from jsonb_each(allowed) loop
    if jsonb_typeof(payload->item.key) <> 'array' then return false; end if;
    if jsonb_array_length(payload->item.key) > jsonb_array_length(item.value) or
      (select count(*) <> count(distinct value) from jsonb_array_elements(payload->item.key)) or
      exists (
        select 1 from jsonb_array_elements(payload->item.key) candidate
        where not exists (
          select 1 from jsonb_array_elements(item.value) permitted
          where permitted.value = candidate.value
        )
      ) then return false; end if;
  end loop;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.is_trip_party_snapshot_v1(payload jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare member jsonb; reference_date text; parsed_date date;
begin
  if not public.is_trip_library_envelope_v1(payload, 'schemaVersion', 131072)
    or (payload - 'schemaVersion' - 'includesOwner' - 'ageReferenceDate' - 'members') <> '{}'::jsonb
    or jsonb_typeof(payload->'includesOwner') is distinct from 'boolean'
    or jsonb_typeof(payload->'ageReferenceDate') is distinct from 'string'
    or jsonb_typeof(payload->'members') is distinct from 'array'
    then return false; end if;
  reference_date := payload->>'ageReferenceDate';
  if reference_date !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then return false; end if;
  parsed_date := make_date(substring(reference_date,1,4)::integer,
    substring(reference_date,6,2)::integer,substring(reference_date,9,2)::integer);
  if extract(year from parsed_date) < 1 or extract(year from parsed_date) > 9999 then return false; end if;
  -- MAX_COMPANIONS_PER_USER, reused from accepted Companion v1; trace IDs have no FK.
  if jsonb_array_length(payload->'members') > 100 then return false; end if;
  for member in select value from jsonb_array_elements(payload->'members') loop
    if jsonb_typeof(member) <> 'object'
      or (member - 'sourceCompanionId' - 'displayName' - 'planningAgeGroup' - 'travelProfile') <> '{}'::jsonb
      or jsonb_typeof(member->'sourceCompanionId') is distinct from 'string'
      or coalesce(member->>'sourceCompanionId' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$', true)
      or jsonb_typeof(member->'displayName') is distinct from 'string'
      or coalesce(char_length(member->>'displayName') not between 1 and 100, true)
      or member->>'displayName' <> btrim(member->>'displayName', E' \t\n\r\f\v')
      or coalesce(member->>'planningAgeGroup' not in ('infant','child','adult','senior'), true)
      or not public.is_companion_travel_profile_v1(member->'travelProfile') then return false; end if;
  end loop;
  if (select count(*) <> count(distinct value->>'sourceCompanionId') from jsonb_array_elements(payload->'members'))
    then return false; end if;
  return true;
exception when datetime_field_overflow or invalid_datetime_format then return false;
end $function$

CREATE OR REPLACE FUNCTION public.mutate_companion_group_v1(p_action text, p_id uuid DEFAULT NULL::uuid, p_expected_revision integer DEFAULT NULL::integer, p_name text DEFAULT NULL::text, p_includes_owner boolean DEFAULT NULL::boolean, p_member_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare
  actor uuid := auth.uid();
  saved public.companion_groups;
  current_revision integer;
  members jsonb;
begin
  if actor is null then raise exception 'AUTH_REQUIRED'; end if;
  perform pg_advisory_xact_lock(hashtextextended(actor::text, 517));
  if p_action not in ('create','update','delete') or p_action is null then raise exception 'INVALID_REQUEST'; end if;
  if p_action <> 'create' then
    if p_expected_revision is null or p_expected_revision < 1 then raise exception 'INVALID_REQUEST'; end if;
    select revision into current_revision from public.companion_groups where id = p_id and owner_user_id = actor for update;
    if not found then raise exception 'COMPANION_GROUP_NOT_FOUND'; end if;
    if current_revision <> p_expected_revision then raise exception 'STALE_COMPANION_GROUP_REVISION'; end if;
  elsif p_id is not null or p_expected_revision is not null then
    raise exception 'INVALID_REQUEST';
  end if;
  if p_action = 'delete' then
    delete from public.companion_groups where id = p_id and owner_user_id = actor and revision = p_expected_revision;
    return null;
  end if;
  if p_member_ids is null or cardinality(p_member_ids) > 20 or
     (select count(*) <> count(distinct member) from unnest(p_member_ids) member) then raise exception 'INVALID_COMPANION_GROUP_INPUT'; end if;
  if exists(select 1 from unnest(p_member_ids) member where member is null or not exists(
    select 1 from public.companions c where c.id = member and c.owner_user_id = actor)) then raise exception 'COMPANION_GROUP_MEMBER_INVALID'; end if;
  if p_action = 'create' then
    if (select count(*) from public.companion_groups where owner_user_id = actor) >= 20 then raise exception 'COMPANION_GROUP_LIMIT_REACHED'; end if;
    insert into public.companion_groups(owner_user_id, name, includes_owner) values(actor, p_name, p_includes_owner) returning * into saved;
  else
    update public.companion_groups set name = p_name, includes_owner = p_includes_owner, revision = revision + 1
      where id = p_id and owner_user_id = actor and revision = p_expected_revision returning * into saved;
    if not found then raise exception 'STALE_COMPANION_GROUP_REVISION'; end if;
    delete from public.companion_group_members where group_id = p_id and owner_user_id = actor;
  end if;
  insert into public.companion_group_members(owner_user_id,group_id,companion_id,sort_order)
    select actor,saved.id,member,(ordinality-1)::integer from unnest(p_member_ids) with ordinality as x(member,ordinality);
  select coalesce(jsonb_agg(to_jsonb(m) order by m.sort_order),'[]'::jsonb) into members
    from public.companion_group_members m where m.group_id = saved.id and m.owner_user_id = actor;
  return jsonb_build_object('group',to_jsonb(saved),'members',members);
end $function$

CREATE OR REPLACE FUNCTION public.mutate_companion_v1(p_action text, p_id uuid DEFAULT NULL::uuid, p_expected_revision integer DEFAULT NULL::integer, p_input jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare
  actor uuid := auth.uid();
  saved public.companions;
  current_revision integer;
begin
  if actor is null then raise exception 'AUTH_REQUIRED'; end if;
  perform pg_advisory_xact_lock(hashtextextended(actor::text, 517));
  if p_action not in ('create','update','delete') or p_action is null then raise exception 'INVALID_REQUEST'; end if;
  if p_action <> 'create' then
    if p_expected_revision is null or p_expected_revision < 1 then raise exception 'INVALID_REQUEST'; end if;
    select revision into current_revision from public.companions where id = p_id and owner_user_id = actor for update;
    if not found then raise exception 'COMPANION_NOT_FOUND'; end if;
    if current_revision <> p_expected_revision then raise exception 'STALE_COMPANION_REVISION'; end if;
  elsif p_id is not null or p_expected_revision is not null then
    raise exception 'INVALID_REQUEST';
  end if;
  if p_action = 'delete' then
    -- Cascade changes the aggregate snapshot: invalidate every affected group
    -- revision in the same transaction so an old editor cannot resurrect it.
    update public.companion_groups g set revision = g.revision + 1
      where g.owner_user_id = actor and exists (
        select 1 from public.companion_group_members m
        where m.group_id = g.id and m.owner_user_id = actor and m.companion_id = p_id);
    delete from public.companions where id = p_id and owner_user_id = actor and revision = p_expected_revision;
    return null;
  end if;
  if p_input is null or jsonb_typeof(p_input) <> 'object' or
     not p_input ?& array['display_name','relationship_code','relationship_label','birth_date','age_group_fallback','gender_code','avatar_path','travel_profile'] or
     (select count(*) from jsonb_object_keys(p_input)) <> 8 then raise exception 'INVALID_COMPANION_INPUT'; end if;
  if p_action = 'create' then
    -- Count limits mirror the sole domain constants; TASK-047 tests check parity.
    if (select count(*) from public.companions where owner_user_id = actor) >= 100 then raise exception 'COMPANION_LIMIT_REACHED'; end if;
    insert into public.companions(owner_user_id, display_name, relationship_code, relationship_label, birth_date, age_group_fallback, gender_code, avatar_path, travel_profile)
      values(actor, p_input->>'display_name', p_input->>'relationship_code', p_input->>'relationship_label', (p_input->>'birth_date')::date, p_input->>'age_group_fallback', p_input->>'gender_code', p_input->>'avatar_path', p_input->'travel_profile')
      returning * into saved;
  else
    update public.companions set
      display_name = p_input->>'display_name', relationship_code = p_input->>'relationship_code',
      relationship_label = p_input->>'relationship_label', birth_date = (p_input->>'birth_date')::date,
      age_group_fallback = p_input->>'age_group_fallback', gender_code = p_input->>'gender_code',
      avatar_path = p_input->>'avatar_path', travel_profile = p_input->'travel_profile', revision = revision + 1
      where id = p_id and owner_user_id = actor and revision = p_expected_revision returning * into saved;
    if not found then raise exception 'STALE_COMPANION_REVISION'; end if;
  end if;
  return to_jsonb(saved);
end $function$

CREATE OR REPLACE FUNCTION public.set_profile_audit_timestamps()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if TG_OP = 'INSERT' then
    NEW.created_at := statement_timestamp();
  else
    NEW.created_at := OLD.created_at;
  end if;
  NEW.updated_at := statement_timestamp();
  return NEW;
end;
$function$
